mapper.update:
UPDATE lambda_code_uploads
SET status = #{status},
    status_date = #{statusDate},
    message = #{message},
    function_name = #{functionName},
    async_function_name = #{asyncFunctionName},
    memory = #{memory},
    timeout = #{timeout}
WHERE upload_id = #{uploadId}
  AND status != #{status}

UPDATE lambda_code_uploads
SET function_name = #{functionName},
    async_function_name = #{asyncFunctionName}
WHERE upload_id = #{uploadId}
  AND status = 'IN_PROGRESS'

UPDATE lambda_code_uploads
SET function_deletion_date = #{deletionDate},
    function_deletion_info = #{deletionInfo}
WHERE upload_id = #{uploadId}
